package dev.oqthara.runtime;

import java.io.BufferedReader;
import java.io.PrintStream;
import java.io.StringReader;
import java.lang.reflect.InvocationTargetException;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.List;

/**
 * Method-call helpers used by generated bytecode. Dispatch is the interpreter's dispatch, not
 * a copy of it: the same {@link MethodResolver} resolves collection, text, number and data
 * methods, and the same {@code JavaBridge} handles the reflective fallback the interpreter
 * uses for Java objects. Both are reached by name because this module sits below them, so
 * there is exactly one implementation of each rule and nothing can drift.
 *
 * <p>Calls to names the resolver does not implement are refused when compiling, not here:
 * the interpreter would fall back to Java reflection, and quietly compiling that path is how
 * a jar starts behaving differently from {@code oq run}.
 */
public final class Methods {
    private Methods() {
    }

    public static Object invoke0(Object receiver, String name) {
        return invoke(receiver, name);
    }

    public static Object invoke1(Object receiver, Object a, String name) {
        return invoke(receiver, name, a);
    }

    public static Object invoke2(Object receiver, Object a, Object b, String name) {
        return invoke(receiver, name, a, b);
    }

    public static Object invoke3(Object receiver, Object a, Object b, Object c, String name) {
        return invoke(receiver, name, a, b, c);
    }

    public static Object invoke4(Object receiver, Object a, Object b, Object c, Object d,
            String name) {
        return invoke(receiver, name, a, b, c, d);
    }

    private static Object invoke(Object receiver, String name, Object... args) {
        Span span = Errors.current();
        if (receiver == null) {
            throw new OqError("cannot call method '" + name + "' on nothing", span,
                    "Check that the value is not nothing before calling a method on it.");
        }
        try {
            return dispatch(receiver, name, args, span);
        } catch (UnsupportedOperationException e) {
            // A collection that refuses to change is a program-visible condition, never an
            // Oqthara defect, so a compiled jar reports it exactly as the interpreter does
            // instead of blaming Oqthara and exiting 70.
            throw Errors.immutableRefusal(e, span);
        }
    }

    private static Object dispatch(Object receiver, String name, Object[] args, Span span) {
        if (!(receiver instanceof Class<?>)) {
            OqCallable method = resolver().resolve(receiver, name, span);
            if (method != null) {
                return method.call(HOST, Arrays.asList(args), span);
            }
        }
        return interop(receiver, name, args, span);
    }

    /**
     * Delegates to {@code dev.oqthara.core.JavaBridge}, the interpreter's own interop code,
     * so overload selection and argument conversion are identical on both backends. The
     * runtime module cannot depend on the interpreter module, which is why this is reflective.
     */
    private static Object interop(Object receiver, String name, Object[] args, Span span) {
        Class<?> bridge = bridge();
        List<Object> list = Arrays.asList(args);
        try {
            if (receiver instanceof Class<?> type) {
                Object result = bridge.getMethod("callStatic", Class.class, String.class,
                                List.class, Span.class, Path.class)
                        .invoke(null, type, name, list, span, Path.of("."));
                if (result != notFound(bridge)) return result;
                throw new OqError("Java class " + type.getSimpleName()
                        + " has no static method '" + name + "'", span);
            }
            Object result = bridge.getMethod("callMethod", Object.class, String.class, List.class,
                            Span.class, Path.class)
                    .invoke(null, receiver, name, list, span, Path.of("."));
            if (result != notFound(bridge)) return result;
        } catch (InvocationTargetException e) {
            Throwable cause = e.getTargetException();
            if (cause instanceof RuntimeException runtime) throw runtime;
            throw new OqError(String.valueOf(cause), span);
        } catch (ReflectiveOperationException e) {
            throw new OqError("method calls need the Oqthara runtime on the classpath",
                    span, e.toString());
        }
        // `xs.next()` and `xs.has_next()` are the two mistakes the iterator protocol (ADR-0020)
        // makes easy, because "iterate this" and "advance this" read alike. Name the fix.
        if (name.equals("next") || name.equals("has_next")) {
            throw new OqError("type " + Values.typeName(receiver) + " has no method '" + name + "'",
                    span, "Call iter() first: " + Values.typeName(receiver)
                            + " is iterable, not an iterator.");
        }
        throw new OqError("type " + Values.typeName(receiver) + " has no method '" + name + "'",
                span, "Check the spelling, or use a built-in function instead.");
    }

    private static Object notFound(Class<?> bridge) throws ReflectiveOperationException {
        return bridge.getField("NOT_FOUND").get(null);
    }

    private static MethodResolver resolver;

    private static MethodResolver resolver() {
        if (resolver == null) {
            try {
                resolver = (MethodResolver) Class.forName("dev.oqthara.stdlib.MethodResolverImpl")
                        .getDeclaredConstructor().newInstance();
            } catch (ReflectiveOperationException e) {
                throw new OqError("method calls need the oq-stdlib method resolver",
                        Span.synthetic(), "It is normally packaged into every generated jar.");
            }
        }
        return resolver;
    }

    private static Class<?> bridge;

    private static Class<?> bridge() {
        if (bridge == null) {
            try {
                bridge = Class.forName("dev.oqthara.core.JavaBridge");
            } catch (ClassNotFoundException e) {
                throw new OqError("method calls need the Oqthara runtime on the classpath",
                        Span.synthetic(), "It is normally packaged into every generated jar.");
            }
        }
        return bridge;
    }

    private static final OqHost HOST = new OqHost() {
        private final BufferedReader in = new BufferedReader(new StringReader(""));

        @Override
        public Object call(Object callee, List<Object> args, Span span) {
            // A compiled lambda reaches a stdlib method such as `map` or `sort_by` through
            // here. It is an ordinary OqCallable, so the method resolves it the same way the
            // interpreter does; anything else gets the interpreter's own diagnostic.
            if (callee instanceof OqCallable callable) {
                return callable.call(this, args, span);
            }
            throw new OqError("'" + Values.typeName(callee) + "' is not a function", span,
                    "This value cannot be called.");
        }

        @Override
        public PrintStream out() {
            return System.out;
        }

        @Override
        public PrintStream err() {
            return System.err;
        }

        @Override
        public BufferedReader in() {
            return in;
        }

        @Override
        public List<String> programArgs() {
            return List.of();
        }

        @Override
        public Path workingDirectory() {
            return Path.of(".");
        }
    };
}
